const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon(
    [[[30.2, 22.9],
      [30.2, 23.3],
      [30.8, 23.3],
      [30.8, 22.9],
      [30.2, 22.9]]], null, false);

  const start2002 = '2002-09-01';
  const end2002 = '2002-09-30';
  const start2012 = '2012-06-01';
  const end2012 = '2012-06-30';

  const scale = 30; // Landsat native resolution

  // Function to mask clouds for Landsat 7 SR data.
  function maskL7sr(image) {
    // Bits 0 and 1 are fill, so ignore them.
    // Bit 2 is calibrated and corrected.
    // Bits 3, 5, 6, 7 are cloud, cloud shadow, cirrus, snow/ice.
    var qa = image.select('pixel_qa');
    var cloudState = qa.bitwiseAnd(1 << 5).or(qa.bitwiseAnd(1 << 6)).or(qa.bitwiseAnd(1 << 7)); // Cloud, Cloud Shadow, Cirrus
    var snowState = qa.bitwiseAnd(1 << 4); // Snow/Ice

    // Both flags should be set for a clear pixel.
    var clear = qa.bitwiseAnd(1 << 6).eq(0) // Not cloud shadow
      .and(qa.bitwiseAnd(1 << 5).eq(0)) // Not cloud
      .and(qa.bitwiseAnd(1 << 3).eq(0)); // Not designated fill or cloud

    return image.updateMask(clear);
  }

  // Function to calculate NDWI and classify water.
  function calculateNDWI(image) {
    var ndwi = image.normalizedDifference(['B2', 'B4']).rename('NDWI'); // Green (B2), NIR (B4) for L7
    var water = ndwi.gt(0.15).rename('water_mask'); // Threshold to classify water.
    return image.addBands(ndwi).addBands(water);
  }

  // 2. Data Acquisition & Check
  let collection2002 = ee.ImageCollection('USGS/LANDSAT/LE07/C01/T1_SR')
    .filterBounds(geometry)
    .filterDate(start2002, end2002)
    .map(maskL7sr)
    .map(calculateNDWI);

  let collection2012 = ee.ImageCollection('USGS/LANDSAT/LE07/C01/T1_SR')
    .filterBounds(geometry)
    .filterDate(start2012, end2012)
    .map(maskL7sr)
    .map(calculateNDWI);

  const size2002 = await collection2002.size().getInfo();
  const size2012 = await collection2012.size().getInfo();

  if (size2002 === 0) {
    console.log("No images found for September 2002.");
    console.log("C1");
    return;
  }
  if (size2012 === 0) {
    console.log("No images found for June 2012.");
    console.log("C1");
    return;
  }

  // Create a median composite for each period
  const image2002 = collection2002.median();
  const image2012 = collection2012.median();

  // 3. Processing (Calculate pixel count to detect C2)
  const waterMask2002 = image2002.select('water_mask');
  const waterMask2012 = image2012.select('water_mask');

  // Calculate valid water pixel count for C2 check
  const waterCount2002 = await waterMask2002.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('water_mask').getInfo();

  const waterCount2012 = await waterMask2012.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('water_mask').getInfo();

  if (waterCount2002 === 0) {
    console.log("No valid water pixels found for September 2002 after masking/processing.");
    console.log("C2");
    return;
  }
  if (waterCount2012 === 0) {
    console.log("No valid water pixels found for June 2012 after masking/processing.");
    console.log("C2");
    return;
  }

  // 4. Calculation (Water area)
  const waterArea2002 = waterMask2002.multiply(ee.Image.pixelArea())
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('water_mask').getInfo();

  const waterArea2012 = waterMask2012.multiply(ee.Image.pixelArea())
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('water_mask').getInfo();

  // 5. Validation & Final Answer
  if (waterArea2002 === null || waterArea2012 === null) {
    console.log("Calculation of water area resulted in null.");
    console.log("C3");
    return;
  }

  const areaSqKm2002 = waterArea2002 / 1e6;
  const areaSqKm2012 = waterArea2012 / 1e6;

  console.log(`2002 Images: ${size2002}, Water Pixels: ${waterCount2002}, Area: ${areaSqKm2002.toFixed(2)} km²`);
  console.log(`2012 Images: ${size2012}, Water Pixels: ${waterCount2012}, Area: ${areaSqKm2012.toFixed(2)} km²`);

  if (areaSqKm2012 < areaSqKm2002) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
